#!/usr/bin/env bash
set -euo pipefail
GSZ=/opt/gsz
F="$GSZ/routes/checkout.js"
TS=$(date +%Y%m%d-%H%M%S); BK="$F.bak-step186-$TS"
echo "==> step186: subscription expiry reminders (auto WhatsApp + email before a line lapses)"
cp "$F" "$BK"; echo "    backup: $BK"
restore(){ echo "!! restoring"; cp "$BK" "$F" 2>/dev/null||true; }
trap 'restore' ERR
echo "==> DB migration"
DBJS=$(mktemp /tmp/db186.XXXXXX.js); echo "" | base64 -d > "$DBJS"
( cd "$GSZ" && NODE_PATH="$GSZ/node_modules" GSZ_ENV="$GSZ/.env" node "$DBJS" )
rm -f "$DBJS"
echo "==> applying worker"
P=$(mktemp /tmp/p186.XXXXXX.js); echo "" | base64 -d > "$P"
NODE_PATH="$GSZ/node_modules" node "$P" "$GSZ"
echo "==> validating"; NODE_PATH="$GSZ/node_modules" node --check "$F" && echo "    checkout.js ok"
echo "==> restarting"; pm2 restart gsz >/dev/null 2>&1 || pm2 restart gsz
CODE=000; for i in $(seq 1 25); do sleep 1; CODE=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3900/ || echo 000); [ "$CODE" = "200" ] && break; done
[ "$CODE" = "200" ] || { echo "    homepage $CODE"; false; }
echo "    homepage 200: OK (after ${i}s)"
rm -f "$P"; trap - ERR
echo ""
echo "==> step186 OK  Active subscriptions get an automatic renew reminder (WhatsApp + email) when they're within 3 days of expiry — once per expiry. Uses the bot's /api/subscription; verified-identity WhatsApp only."
